/* Phase 1 foundation only: no tax calculation, no seed classifications/rates, no legacy item rewrite. */
SET XACT_ABORT ON;
GO
IF OBJECT_ID(N'dbo.HsnSacMasters',N'U') IS NULL CREATE TABLE dbo.HsnSacMasters(Id BIGINT IDENTITY PRIMARY KEY,Code NVARCHAR(50) NOT NULL,CodeType NVARCHAR(3) NOT NULL,Description NVARCHAR(500) NOT NULL,IsActive BIT NOT NULL CONSTRAINT DF_HsnSac_Active DEFAULT 1,CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_HsnSac_Created DEFAULT SYSUTCDATETIME(),CreatedBy BIGINT NULL,UpdatedAtUtc DATETIME2(3) NULL,UpdatedBy BIGINT NULL,IsDeleted BIT NOT NULL CONSTRAINT DF_HsnSac_Deleted DEFAULT 0,CONSTRAINT CK_HsnSac_Type CHECK(CodeType IN(N'HSN',N'SAC')));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'UX_HsnSacMasters_Code' AND object_id=OBJECT_ID(N'dbo.HsnSacMasters')) CREATE UNIQUE INDEX UX_HsnSacMasters_Code ON dbo.HsnSacMasters(Code) WHERE IsDeleted=0;
IF OBJECT_ID(N'dbo.GstRateRules',N'U') IS NULL CREATE TABLE dbo.GstRateRules(Id BIGINT IDENTITY PRIMARY KEY,RuleCode NVARCHAR(100) NOT NULL,CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_GstRateRules_Created DEFAULT SYSUTCDATETIME(),CreatedBy BIGINT NULL,IsDeleted BIT NOT NULL CONSTRAINT DF_GstRateRules_Deleted DEFAULT 0);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=N'UX_GstRateRules_Code' AND object_id=OBJECT_ID(N'dbo.GstRateRules')) CREATE UNIQUE INDEX UX_GstRateRules_Code ON dbo.GstRateRules(RuleCode) WHERE IsDeleted=0;
IF OBJECT_ID(N'dbo.GstRateRuleVersions',N'U') IS NULL CREATE TABLE dbo.GstRateRuleVersions(Id BIGINT IDENTITY PRIMARY KEY,GstRateRuleId BIGINT NOT NULL,VersionNumber INT NOT NULL,TotalRate DECIMAL(5,2) NOT NULL,EffectiveFrom DATE NOT NULL,EffectiveTo DATE NULL,IsActive BIT NOT NULL CONSTRAINT DF_GstRateVersion_Active DEFAULT 1,Notes NVARCHAR(1000) NULL,CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_GstRateVersion_Created DEFAULT SYSUTCDATETIME(),CreatedBy BIGINT NULL,CONSTRAINT FK_GstRateVersion_Rule FOREIGN KEY(GstRateRuleId) REFERENCES dbo.GstRateRules(Id),CONSTRAINT UQ_GstRateVersion_Number UNIQUE(GstRateRuleId,VersionNumber),CONSTRAINT CK_GstRateVersion_Rate CHECK(TotalRate>=0 AND TotalRate<=100),CONSTRAINT CK_GstRateVersion_Dates CHECK(EffectiveTo IS NULL OR EffectiveTo>=EffectiveFrom));
IF OBJECT_ID(N'dbo.CategoryHsnDefaults',N'U') IS NULL CREATE TABLE dbo.CategoryHsnDefaults(Id BIGINT IDENTITY PRIMARY KEY,CategoryId BIGINT NOT NULL,HsnSacId BIGINT NOT NULL,EffectiveFrom DATE NOT NULL,EffectiveTo DATE NULL,CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_CategoryHsn_Created DEFAULT SYSUTCDATETIME(),CreatedBy BIGINT NULL,CONSTRAINT FK_CategoryHsn_Category FOREIGN KEY(CategoryId) REFERENCES dbo.Categories(Id),CONSTRAINT FK_CategoryHsn_Hsn FOREIGN KEY(HsnSacId) REFERENCES dbo.HsnSacMasters(Id),CONSTRAINT CK_CategoryHsn_Dates CHECK(EffectiveTo IS NULL OR EffectiveTo>=EffectiveFrom));
IF OBJECT_ID(N'dbo.ItemHsnOverrides',N'U') IS NULL CREATE TABLE dbo.ItemHsnOverrides(Id BIGINT IDENTITY PRIMARY KEY,ItemId BIGINT NOT NULL,HsnSacId BIGINT NOT NULL,EffectiveFrom DATE NOT NULL,EffectiveTo DATE NULL,CreatedAtUtc DATETIME2(3) NOT NULL CONSTRAINT DF_ItemHsn_Created DEFAULT SYSUTCDATETIME(),CreatedBy BIGINT NULL,CONSTRAINT FK_ItemHsn_Item FOREIGN KEY(ItemId) REFERENCES dbo.Items(Id),CONSTRAINT FK_ItemHsn_Hsn FOREIGN KEY(HsnSacId) REFERENCES dbo.HsnSacMasters(Id),CONSTRAINT CK_ItemHsn_Dates CHECK(EffectiveTo IS NULL OR EffectiveTo>=EffectiveFrom));
GO
CREATE OR ALTER PROCEDURE dbo.usp_HsnSac_List @Search NVARCHAR(200)=NULL,@CodeType NVARCHAR(3)=NULL,@IsActive BIT=NULL,@PageNumber INT=1,@PageSize INT=20 AS SELECT Id,Code,CodeType,Description,IsActive,CreatedAtUtc,UpdatedAtUtc,COUNT(1)OVER() TotalCount FROM dbo.HsnSacMasters WHERE IsDeleted=0 AND(@Search IS NULL OR Code LIKE N'%'+@Search+N'%' OR Description LIKE N'%'+@Search+N'%')AND(@CodeType IS NULL OR CodeType=@CodeType)AND(@IsActive IS NULL OR IsActive=@IsActive) ORDER BY Code OFFSET(@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
GO
CREATE OR ALTER PROCEDURE dbo.usp_HsnSac_Get @Id BIGINT AS SELECT Id,Code,CodeType,Description,IsActive,CreatedAtUtc,UpdatedAtUtc FROM dbo.HsnSacMasters WHERE Id=@Id AND IsDeleted=0;
GO
CREATE OR ALTER PROCEDURE dbo.usp_HsnSac_Save @Id BIGINT=NULL,@Code NVARCHAR(50),@CodeType NVARCHAR(3),@Description NVARCHAR(500),@IsActive BIT,@UserId BIGINT=NULL AS BEGIN SET NOCOUNT ON;SET @Code=UPPER(LTRIM(RTRIM(@Code)));IF @Id IS NULL BEGIN IF EXISTS(SELECT 1 FROM dbo.HsnSacMasters WHERE Code=@Code AND IsDeleted=0) BEGIN SELECT 409 StatusCode,N'HSN/SAC code already exists.' Message;RETURN;END INSERT dbo.HsnSacMasters(Code,CodeType,Description,IsActive,CreatedBy)VALUES(@Code,@CodeType,@Description,@IsActive,@UserId);SET @Id=SCOPE_IDENTITY();END ELSE BEGIN IF @IsActive=0 AND EXISTS(SELECT 1 FROM dbo.ItemHsnOverrides WHERE HsnSacId=@Id AND(EffectiveTo IS NULL OR EffectiveTo>=CAST(SYSUTCDATETIME() AS DATE))) BEGIN SELECT 409 StatusCode,N'Cannot deactivate an HSN/SAC referenced by an active product mapping.' Message;RETURN;END UPDATE dbo.HsnSacMasters SET Code=@Code,CodeType=@CodeType,Description=@Description,IsActive=@IsActive,UpdatedAtUtc=SYSUTCDATETIME(),UpdatedBy=@UserId WHERE Id=@Id AND IsDeleted=0;END SELECT 200 StatusCode,N'HSN/SAC saved.' Message;EXEC dbo.usp_HsnSac_Get @Id;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_GstRateRuleVersion_List @RuleCode NVARCHAR(100)=NULL,@ApplicableOn DATE=NULL,@IsActive BIT=NULL,@PageNumber INT=1,@PageSize INT=20 AS SELECT v.Id,r.RuleCode,v.VersionNumber,v.TotalRate,v.EffectiveFrom,v.EffectiveTo,v.IsActive,v.Notes,v.CreatedAtUtc,COUNT(1)OVER() TotalCount FROM dbo.GstRateRuleVersions v JOIN dbo.GstRateRules r ON r.Id=v.GstRateRuleId AND r.IsDeleted=0 WHERE(@RuleCode IS NULL OR r.RuleCode=@RuleCode)AND(@IsActive IS NULL OR v.IsActive=@IsActive)AND(@ApplicableOn IS NULL OR v.EffectiveFrom<=@ApplicableOn AND(v.EffectiveTo IS NULL OR v.EffectiveTo>=@ApplicableOn)) ORDER BY r.RuleCode,v.EffectiveFrom DESC OFFSET(@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
GO
CREATE OR ALTER PROCEDURE dbo.usp_GstRateRuleVersion_Save @RuleCode NVARCHAR(100),@TotalRate DECIMAL(5,2),@EffectiveFrom DATE,@EffectiveTo DATE=NULL,@IsActive BIT=1,@Notes NVARCHAR(1000)=NULL,@UserId BIGINT=NULL AS BEGIN SET NOCOUNT ON;SET @RuleCode=UPPER(LTRIM(RTRIM(@RuleCode)));DECLARE @RuleId BIGINT=(SELECT Id FROM dbo.GstRateRules WHERE RuleCode=@RuleCode AND IsDeleted=0);IF @RuleId IS NULL BEGIN INSERT dbo.GstRateRules(RuleCode,CreatedBy)VALUES(@RuleCode,@UserId);SET @RuleId=SCOPE_IDENTITY();END IF EXISTS(SELECT 1 FROM dbo.GstRateRuleVersions WHERE GstRateRuleId=@RuleId AND IsActive=1 AND @IsActive=1 AND EffectiveFrom<=ISNULL(@EffectiveTo,'99991231') AND @EffectiveFrom<=ISNULL(EffectiveTo,'99991231')) BEGIN SELECT 409 StatusCode,N'Active rate-rule effective dates overlap.' Message;RETURN;END DECLARE @Version INT=ISNULL((SELECT MAX(VersionNumber) FROM dbo.GstRateRuleVersions WHERE GstRateRuleId=@RuleId),0)+1;INSERT dbo.GstRateRuleVersions(GstRateRuleId,VersionNumber,TotalRate,EffectiveFrom,EffectiveTo,IsActive,Notes,CreatedBy)VALUES(@RuleId,@Version,@TotalRate,@EffectiveFrom,@EffectiveTo,@IsActive,@Notes,@UserId);SELECT 201 StatusCode,N'GST rate version saved.' Message;SELECT v.Id,r.RuleCode,v.VersionNumber,v.TotalRate,v.EffectiveFrom,v.EffectiveTo,v.IsActive,v.Notes,v.CreatedAtUtc FROM dbo.GstRateRuleVersions v JOIN dbo.GstRateRules r ON r.Id=v.GstRateRuleId WHERE v.Id=SCOPE_IDENTITY();END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_CategoryHsnDefault_Save @CategoryId BIGINT,@HsnSacId BIGINT,@EffectiveFrom DATE,@EffectiveTo DATE=NULL,@UserId BIGINT=NULL AS BEGIN IF NOT EXISTS(SELECT 1 FROM dbo.HsnSacMasters WHERE Id=@HsnSacId AND IsActive=1 AND IsDeleted=0) BEGIN SELECT 400 StatusCode,N'HSN/SAC must be active.' Message;RETURN;END INSERT dbo.CategoryHsnDefaults(CategoryId,HsnSacId,EffectiveFrom,EffectiveTo,CreatedBy)VALUES(@CategoryId,@HsnSacId,@EffectiveFrom,@EffectiveTo,@UserId);SELECT 200 StatusCode,N'Category mapping saved.' Message;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ItemHsnOverride_Save @ItemId BIGINT,@HsnSacId BIGINT,@EffectiveFrom DATE,@EffectiveTo DATE=NULL,@UserId BIGINT=NULL AS BEGIN IF NOT EXISTS(SELECT 1 FROM dbo.HsnSacMasters WHERE Id=@HsnSacId AND IsActive=1 AND IsDeleted=0) BEGIN SELECT 400 StatusCode,N'HSN/SAC must be active.' Message;RETURN;END INSERT dbo.ItemHsnOverrides(ItemId,HsnSacId,EffectiveFrom,EffectiveTo,CreatedBy)VALUES(@ItemId,@HsnSacId,@EffectiveFrom,@EffectiveTo,@UserId);SELECT 200 StatusCode,N'Product override saved.' Message;END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ItemHsn_Resolve @ItemId BIGINT,@OnDate DATE AS BEGIN ;WITH candidates AS(SELECT i.Id ItemId,h.Id HsnSacId,h.Code,h.CodeType,h.Description,N'ProductOverride' Source,m.EffectiveFrom,m.EffectiveTo,i.HSNCode LegacyHsnCode,1 Priority FROM dbo.Items i JOIN dbo.ItemHsnOverrides m ON m.ItemId=i.Id JOIN dbo.HsnSacMasters h ON h.Id=m.HsnSacId AND h.IsActive=1 AND h.IsDeleted=0 WHERE i.Id=@ItemId AND m.EffectiveFrom<=@OnDate AND(m.EffectiveTo IS NULL OR m.EffectiveTo>=@OnDate) UNION ALL SELECT i.Id,h.Id,h.Code,h.CodeType,h.Description,N'CategoryDefault',m.EffectiveFrom,m.EffectiveTo,i.HSNCode,2 FROM dbo.Items i JOIN dbo.CategoryHsnDefaults m ON m.CategoryId=i.CategoryId JOIN dbo.HsnSacMasters h ON h.Id=m.HsnSacId AND h.IsActive=1 AND h.IsDeleted=0 WHERE i.Id=@ItemId AND m.EffectiveFrom<=@OnDate AND(m.EffectiveTo IS NULL OR m.EffectiveTo>=@OnDate)) SELECT TOP 1 ItemId,HsnSacId,Code,CodeType,Description,Source,EffectiveFrom,EffectiveTo,LegacyHsnCode FROM candidates ORDER BY Priority,EffectiveFrom DESC;IF @@ROWCOUNT=0 SELECT Id ItemId,CAST(NULL AS BIGINT)HsnSacId,CAST(NULL AS NVARCHAR(50))Code,CAST(NULL AS NVARCHAR(3))CodeType,CAST(NULL AS NVARCHAR(500))Description,N'Missing' Source,CAST(NULL AS DATE)EffectiveFrom,CAST(NULL AS DATE)EffectiveTo,HSNCode LegacyHsnCode FROM dbo.Items WHERE Id=@ItemId;END;
GO
IF OBJECT_ID(N'dbo.Pages',N'U') IS NOT NULL BEGIN
 MERGE dbo.Pages AS t USING(VALUES(N'GST.HsnSac',N'HSN/SAC Master',N'/gst/hsn-sac',N'barcode',306),(N'GST.RateHistory',N'GST Rate History',N'/gst/rate-history',N'calendar-clock',307),(N'GST.CategoryMapping',N'GST Category Mapping',N'/gst/category-mappings',N'tags',308),(N'GST.ProductMapping',N'GST Product Mapping',N'/gst/product-mappings',N'package-check',309))s(Name,DisplayName,Route,Icon,SortOrder) ON t.Name=s.Name WHEN MATCHED THEN UPDATE SET DisplayName=s.DisplayName,Route=s.Route,Icon=s.Icon,SortOrder=s.SortOrder,IsActive=1 WHEN NOT MATCHED THEN INSERT(Name,DisplayName,Route,Icon,SortOrder,IsActive)VALUES(s.Name,s.DisplayName,s.Route,s.Icon,s.SortOrder,1);
 DECLARE @RoleId INT=(SELECT Id FROM dbo.Roles WHERE Name=N'SuperAdmin'); IF @RoleId IS NOT NULL MERGE dbo.RolePermissions AS t USING(SELECT @RoleId RoleId,Id PageId FROM dbo.Pages WHERE Name IN(N'GST.HsnSac',N'GST.RateHistory',N'GST.CategoryMapping',N'GST.ProductMapping'))s ON t.RoleId=s.RoleId AND t.PageId=s.PageId WHEN MATCHED THEN UPDATE SET CanView=1,CanCreate=1,CanEdit=1,CanDelete=1 WHEN NOT MATCHED THEN INSERT(RoleId,PageId,CanView,CanCreate,CanEdit,CanDelete,CanExport,CanApprove)VALUES(s.RoleId,s.PageId,1,1,1,1,0,0);
END;
GO
